('T011', 'TRD-WS', 'ACC', 'รายเดือน', 'ตรวจสต็อกสินค้า กระทบยอดซื้อ-ขาย-คงเหลือ', 'รายงานสินค้าคงเหลือตรงกับบัญชี'),
('T012', 'TRD-WS', 'ACC', 'รายเดือน', 'กระทบยอดลูกหนี้-เจ้าหนี้การค้า ตามอายุหนี้', 'Aging report ลูกหนี้เกินกำหนดมีคำอธิบาย'),
('T013', 'TRD-WS', 'ANN', 'รายปี', 'ตรวจนับสต็อกสิ้นปี คำนวณต้นทุนขาย ตั้งค่าเผื่อสินค้าเสื่อม', 'ใบตรวจนับ + ต้นทุนขายกระทบยอดได้'),
('T014', 'SVC', 'ACC', 'รายเดือน', 'กระทบยอดภาษีถูกหัก ณ ที่จ่าย กับหนังสือรับรองที่ได้รับ', 'ทะเบียน WHT ครบ ใช้เครดิตภาษีได้เต็ม'),
('T015', 'SVC', 'ACC', 'รายเดือน', 'ตรวจรายได้ค้างรับ / งานที่ยังไม่ได้ออกใบแจ้งหนี้', 'รายได้รับรู้ครบถ้วนตามงวดงาน'),
('T016', 'MFG', 'ACC', 'รายเดือน', 'บันทึกต้นทุนการผลิต แยกวัตถุดิบ-ค่าแรง-โสหุ้ย', 'ต้นทุนการผลิตต่อเดือนกระทบยอดกับ GL'),
('T017', 'MFG', 'ACC', 'รายเดือน', 'ตรวจวัตถุดิบ/WIP/สำเร็จรูป กระทบยอดสต็อก', 'รายงานสต็อก 3 ประเภทตรงกับบัญชี'),
('T018', 'MFG', 'ANN', 'รายปี', 'ตรวจนับสต็อกและทะเบียนสินทรัพย์ คำนวณค่าเสื่อมทั้งปี', 'ทะเบียน FA + ค่าเสื่อมตรงกับ GL');

