-- ========== ตรวจผล ==========
select 'client' as ตาราง, count(*) as จำนวนแถว from client
union all select 'business_nature', count(*) from business_nature
union all select 'staff', count(*) from staff
union all select 'service_job', count(*) from service_job
union all select 'task_template', count(*) from task_template
union all select 'coa_mapping', count(*) from coa_mapping
union all select 'assignment', count(*) from assignment
union all select 'workload_year', count(*) from workload_year
union all select 'financial_period', count(*) from financial_period
order by 1;